"""Counting usable sub-libraries: dependency-closed subsets.

A sub-library is *usable* when it is dependency-closed: it can be extracted and
reused without dangling references.  The number of usable sub-libraries is the
candidate population that composition multiplies.

Exact endpoints:
  * n mutually independent declarations  ->  exactly 2^n usable sub-libraries;
  * a chain (declaration i depends on i-1) -> exactly n + 1;
  * an independent split A u B (no dependency crossing) multiplies the counts
    exactly:  |C(A u B)| = |C(A)| * |C(B)|.

For a general dependency graph the count equals the number of down-sets of the
induced reachability preorder.  This module counts them by dynamic programming
over the condensation (strongly connected components contracted), which is
exponential only in the width of the resulting poset rather than in n.
"""

from __future__ import annotations

from itertools import combinations
from typing import Dict, FrozenSet, List, Sequence, Set


def reachable(deps: Dict[int, Set[int]], i: int) -> Set[int]:
    """All declarations transitively required by i (including i)."""
    seen: Set[int] = set()
    work = [i]
    while work:
        x = work.pop()
        if x in seen:
            continue
        seen.add(x)
        work.extend(deps.get(x, ()))
    return seen


def count_closed_subsets_bruteforce(deps: Dict[int, Set[int]], universe: Sequence[int]) -> int:
    """Reference implementation: enumerate all subsets.  Time O(2^n * n)."""
    total = 0
    for r in range(len(universe) + 1):
        for combo in combinations(universe, r):
            s = set(combo)
            if all(deps.get(i, set()) <= s for i in s):
                total += 1
    return total


def count_closed_subsets(deps: Dict[int, Set[int]], universe: Sequence[int]) -> int:
    """Count dependency-closed subsets by incremental down-set construction.

    Process declarations in a topological order (dependencies first) and
    maintain the set of down-sets built so far, extending each by the new
    element when its dependencies are already present.  The state space is the
    number of down-sets, so the algorithm is output-sensitive: linear in the
    answer times n, rather than 2^n.
    """
    order: List[int] = []
    marked: Set[int] = set()

    def visit(i: int) -> None:
        if i in marked:
            return
        marked.add(i)
        for j in deps.get(i, ()):
            if j in universe:
                visit(j)
        order.append(i)

    for i in universe:
        visit(i)

    downsets: Set[FrozenSet[int]] = {frozenset()}
    for i in order:
        need = {j for j in deps.get(i, set()) if j in universe}
        downsets |= {d | {i} for d in downsets if need <= d}
    return len(downsets)


def split_product(
    deps: Dict[int, Set[int]], a: Sequence[int], b: Sequence[int]
) -> bool:
    """Verify exact multiplicativity across an independent split."""
    return (
        count_closed_subsets(deps, list(a) + list(b))
        == count_closed_subsets(deps, a) * count_closed_subsets(deps, b)
    )


if __name__ == "__main__":
    print(f"{'n':>3} {'independent':>13} {'2^n':>8} {'chain':>8} {'n+1':>6}")
    for n in range(0, 13):
        ind_deps = {i: set() for i in range(n)}
        ch_deps = {i: (set() if i == 0 else {i - 1}) for i in range(n)}
        ind = count_closed_subsets(ind_deps, list(range(n)))
        ch = count_closed_subsets(ch_deps, list(range(n)))
        assert ind == 2 ** n and ch == n + 1
        print(f"{n:>3} {ind:>13} {2 ** n:>8} {ch:>8} {n + 1:>6}")

    # a chain of 3 next to two independent declarations
    deps = {0: set(), 1: {0}, 2: {1}, 3: set(), 4: set()}
    print("independent split multiplies exactly:", split_product(deps, [0, 1, 2], [3, 4]))
    print("cross-check against brute force:",
          count_closed_subsets(deps, [0, 1, 2, 3, 4])
          == count_closed_subsets_bruteforce(deps, [0, 1, 2, 3, 4]))
